create table if not exists public.financial_settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
create table if not exists public.ledger_accounts (id uuid primary key default gen_random_uuid(), owner_type text not null check (owner_type in ('platform','merchant','rider')), owner_id uuid, currency text not null default 'NGN', created_at timestamptz not null default now(), unique(owner_type, owner_id));
create table if not exists public.ledger_entries (id uuid primary key default gen_random_uuid(), account_id uuid not null references public.ledger_accounts(id), order_group_id uuid references public.order_groups(id), order_id uuid references public.orders(id), payment_id uuid references public.payments(id), entry_type text not null check (entry_type in ('payment_capture','merchant_allocation','platform_commission','refund','reversal','settlement_hold','settlement_release','adjustment')), direction text not null check (direction in ('debit','credit')), amount_kobo integer not null check (amount_kobo >= 0), currency text not null default 'NGN', idempotency_key text not null unique, reversed_by uuid references public.ledger_entries(id), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.merchant_settlements (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references public.merchants(id), amount_kobo integer not null check (amount_kobo >= 0), currency text not null default 'NGN', status text not null default 'requested' check (status in ('requested','processing','paid','failed','cancelled')), provider_reference text, failure_reason text, idempotency_key text not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.refunds (id uuid primary key default gen_random_uuid(), payment_id uuid not null references public.payments(id), order_group_id uuid not null references public.order_groups(id), order_id uuid references public.orders(id), amount_kobo integer not null check (amount_kobo >= 0), reason text not null, status text not null default 'requested' check (status in ('requested','approved','processing','completed','failed','rejected')), provider_reference text, idempotency_key text not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create trigger set_updated before update on public.merchant_settlements for each row execute function public.set_updated_at();
create trigger set_updated before update on public.refunds for each row execute function public.set_updated_at();
